head.script:
// 화면 리사이징

scwin.clickId;
scwin.gIsurCd;
scwin.clickBzProcsNo;
scwin.clickListBzDtlTpCd;
scwin.clickListInvstgBzTpCd;
scwin.clickListProcsStatCd;
scwin.clickListInvstgAttachFileTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 3)); // 3달전 날짜
        edt_EDate.setValue(vCurDate);
        if (js_market === '1' || js_market === '2' || js_market === '6') {
            rdo_MKT_ID.setValue(js_market);
            rdo_MKT_ID.setDisabled(true);
        } else {
            rdo_MKT_ID.setValue('9');
            rdo_MKT_ID.setDisabled(false);
        }
        await scwin.listSync();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            scwin.gIsurCd = dts_irCeoList.getCellData(row, "ISUR_CD");
            if (colid === 'CONTN_TITLE') {
                if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") === "1") {
                    // 업로드(제출)
                    const options = {
                        id: "ULDSTF07244",
                        title: "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 상세",
                        type: "browserPopup",
                        width: "1010px",
                        height: "300px",
                        callbackFn: "scwin.popupCallback"
                    };

                    $c.win.openPopup("/lstinvstg/ULDSTF07244.gfm", options);
                    await scwin.listSync();
                } else if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") === "2") {
                    // 접수(처리)
                    const options = {
                        id: "ULDSTF07245",
                        title: "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정",
                        type: "browserPopup",
                        width: "750px",
                        height: "590px",
                        callbackFn: "scwin.popupCallback"
                    };

                    $c.win.openPopup("/lstinvstg/ULDSTF07245.gfm", options);
                    await scwin.listSync();
                }
            } else if (colid === "COM_NM") {
                $c.stf.fn_PopupCorpInfo();
            } else if (colid === 'LIST_PROCS_STAT_NM') {
                if (dts_irCeoList.getCellData(dts_irCeoList.getRowPosition(), "GUBUN") === "1") {
                    // 업로드(제출)
                    if ("34" === dts_irCeoList.getCellData(row, 'LIST_PROCS_STAT_CD')) {
                        scwin.setParam(row);
                        // 수정요청 리스트 팝업창
                        const options = {
                            id: "ULDSTF07243",
                            title: "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정요청 리스트",
                            type: "browserPopup",
                            width: "940px",
                            height: "280px",
                            callbackFn: "scwin.popupCallback"
                        };

                        $c.win.openPopup("/lstinvstg/ULDSTF07243.gfm", options);
                    }
                } else {
                    // 접수(처리)
                    await $c.win.alert("해당건은  업로드(제출)인 경우에 한하여 승인여부가 가능합니다.");
                    return;
                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.clickId = "input";
        const options = {
            id: "ULDSTF07245",
            title: "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 등록",
            type: "browserPopup",
            width: "745px",
            height: "590px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstinvstg/ULDSTF07245.gfm", options);
        scwin.clickId = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_irCeoList_OnFail
 * @description ir Ceo List On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_irCeoList_OnFail = async function() {
    try {
        await $c.win.alert(dts_irCeoList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.dts_irCeoList_OnFail" });
    }
};

/**
 * @method
 * @name dts_irCeoList_OnLoadError
 * @description dts_irCeoList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_irCeoList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_irCeoList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.dts_irCeoList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_irCeoList_OnLoadCompleted
 * @description dts_irCeoList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_irCeoList_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_irCeoList.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.dts_irCeoList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF07242.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "신규상장 기업분석/사업모델평가및기업계속성 보고서 관리", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name txb_Title_onkeydown
 * @description txb_Title 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_Title_onkeydown = async function() {
    try {
        if (window.event.keyCode === "13") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.txb_Title_onkeydown" });
    }
};

/**
 * @method
 * @name tbx_wrt_inst_nm_onkeydown
 * @description tbx_wrt_inst_nm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tbx_wrt_inst_nm_onkeydown = async function() {
    try {
        if (window.event.keyCode === "13") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.tbx_wrt_inst_nm_onkeydown" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.Grd_com_isur_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    let vKosdaq_Bbs_Tp_Cd_1 = '';
    let vKosdaq_Bbs_Tp_Cd_2 = '';
    if (cmb_Kosdaq_Bbs_Tp_Cd.getValue() === '12') {
        vKosdaq_Bbs_Tp_Cd_1 = '170';
    } else {
        vKosdaq_Bbs_Tp_Cd_1 = cmb_Kosdaq_Bbs_Tp_Cd.getValue();
    }
    if (cmb_Kosdaq_Bbs_Tp_Cd.getValue() === '180') {
        vKosdaq_Bbs_Tp_Cd_2 = '13';
    } else {
        vKosdaq_Bbs_Tp_Cd_2 = cmb_Kosdaq_Bbs_Tp_Cd.getValue();
    }
    const url = "/listingCommon.do?SCREN_ID=" + "ULDSTF07242.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=FORNCOM_ANLRPT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.nwlist.forncom.anlrpt.list" + "&{P}param01=" + txb_isur_cd.getValue() + // 	회사명
        "&{P}param02=" + txb_isur_cd.getValue() + // 	회사명
        "&{P}param03=" + rdo_MKT_ID.getValue() + // 	시장구분
        "&{P}param04=" + rdo_MKT_ID.getValue() + // 	시장구분
        "&{P}param05=" + vKosdaq_Bbs_Tp_Cd_1 + // 	보고서구분
        "&{P}param06=" + vKosdaq_Bbs_Tp_Cd_1 + // 	보고서구분
        "&{P}param07=" + edt_SDate.getValue() + //	조회시작일자
        "&{P}param08=" + edt_EDate.getValue() + //	조회종료일자
        "&{P}param09=" + txb_Title.getValue() + // 	제목
        "&{P}param10=" + txb_Title.getValue() + //	제목
        "&{P}param11=" + tbx_wrt_inst_nm.getValue() + //	작성기관
        "&{P}param12=" + tbx_wrt_inst_nm.getValue() + //	작성기관
        "&{P}param13=" + rdo_GUBUN.getValue() + //	업로드여부
        "&{P}param14=" + rdo_GUBUN.getValue() + //	업로드여부
        "&{P}param15=" + txb_isur_cd.getValue() + // 	회사명
        "&{P}param16=" + txb_isur_cd.getValue() + // 	회사명
        "&{P}param17=" + rdo_MKT_ID.getValue() + // 	시장구분
        "&{P}param18=" + rdo_MKT_ID.getValue() + // 	시장구분
        "&{P}param19=" + vKosdaq_Bbs_Tp_Cd_2 + // 	보고서구분
        "&{P}param20=" + vKosdaq_Bbs_Tp_Cd_2 + // 	보고서구분
        "&{P}param21=" + edt_SDate.getValue() + //	조회시작일자
        "&{P}param22=" + edt_EDate.getValue() + //	조회종료일자
        "&{P}param23=" + txb_Title.getValue() + // 	제목
        "&{P}param24=" + txb_Title.getValue() + //	제목
        "&{P}param25=" + tbx_wrt_inst_nm.getValue() + //	작성기관
        "&{P}param26=" + tbx_wrt_inst_nm.getValue() + //	작성기관
        "&{P}param27=" + rdo_GUBUN.getValue() + //	업로드여부
        "&{P}param28=" + rdo_GUBUN.getValue(); //	업로드여부

    dts_irCeoList.DataID = encodeURI(url);
    dts_irCeoList.reset();
};

/**
 * @method
 * @name setId
 * @description set Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setId = function(obj) {
    if (scwin.clickId !== "input") {
        scwin.clickId = dts_irCeoList.getCellData(Number(obj), "BZ_PROCS_NO");
    }
};

/**
 * @method
 * @name getId
 * @description get Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getId = function() {
    return scwin.clickId;
};

/**
 * @method
 * @name setParam
 * @description set Param 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function(obj) {
    scwin.clickBzProcsNo = dts_irCeoList.getCellData(Number(obj), 'BZ_PROCS_NO');
    scwin.clickListBzDtlTpCd = dts_irCeoList.getCellData(Number(obj), 'LIST_BZ_DTL_TP_CD');
    scwin.clickListInvstgBzTpCd = dts_irCeoList.getCellData(Number(obj), 'LIST_INVSTG_BZ_TP_CD');
    scwin.clickListProcsStatCd = dts_irCeoList.getCellData(Number(obj), 'LIST_PROCS_STAT_CD');
    scwin.clickListInvstgAttachFileTpCd = dts_irCeoList.getCellData(Number(obj), 'LIST_INVSTG_ATTACH_FILE_TP_CD');
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]\n\n다시 입력해주세요.");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
